describe("Cart — async checkout()", () => {
  it("returns totals and lines for a basic checkout", async () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(1000);
    expect(result.lines).toHaveLength(1);
  });

  it("refreshes prices via priceFetcher before computing totals", async () => {
    const cart = new Cart();
    cart.add(productA, 1); // original price 1000
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };
    const result = await cart.checkout({ priceFetcher });
    expect(result.totals.subtotalCents).toBe(1500);
    expect(result.lines[0]!.product.unitPriceCents).toBe(1500);
  });

  it("validates inventory and passes for available items", async () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
    expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
  });

  it("throws InventoryError when item is unavailable", async () => {
    const cart = new Cart();
    cart.add(productA, 5);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        reason: "out of stock",
      }),
    };
    await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(
      InventoryError,
    );
    try {
      await cart.checkout({ inventoryChecker });
    } catch (e) {
      const err = e as InventoryError;
      expect(err.productId).toBe("a");
      expect(err.requested).toBe(5);
    }
  });

  it("throws InventoryError on partial-stock denial (availableQuantity < requested)", async () => {
    const cart = new Cart();
    cart.add(productA, 10);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };
    await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(
      InventoryError,
    );
    try {
      await cart.checkout({ inventoryChecker });
    } catch (e) {
      const err = e as InventoryError;
      expect(err.productId).toBe("a");
      expect(err.requested).toBe(10);
      expect(err.available).toBe(3);
    }
  });

  it("uses asyncTaxProvider to compute tax", async () => {
    const taxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const cart = new Cart({ region: "US" });
    cart.add(productA, 1); // subtotal=1000, no discount, discountedSubtotal=1000
    const result = await cart.checkout({ asyncTaxProvider: taxProvider });
    // 10% of 1000 = 100
    expect(result.totals.taxCents).toBe(100);
    expect(result.totals.totalCents).toBe(1100);
    expect(taxProvider.getRate).toHaveBeenCalledWith("US");
  });

  it("applies discount before async tax", async () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(300),
    };
    const taxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const cart = new Cart({ discountPolicy });
    cart.add(productA, 1); // subtotal=1000, discount=300, discounted=700
    const result = await cart.checkout({ asyncTaxProvider: taxProvider });
    // 10% of 700 = 70
    expect(result.totals.discountCents).toBe(300);
    expect(result.totals.taxCents).toBe(70);
  });

  it("combines priceFetcher + inventoryChecker + asyncTaxProvider + shipping", async () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(100),
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(2000),
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.05),
    };
    const cart = new Cart({ discountPolicy, shippingCalculator, region: "DE" });
    cart.add(productA, 2);
    const result = await cart.checkout({
      priceFetcher,
      inventoryChecker,
      asyncTaxProvider,
    });
    // refreshed subtotal: 2000 * 2 = 4000
    expect(result.totals.subtotalCents).toBe(4000);
    // discount: 100, discounted: 3900
    expect(result.totals.discountCents).toBe(100);
    // tax: 5% of 3900 = 195
    expect(result.totals.taxCents).toBe(195);
    // shipping: 500
    expect(result.totals.shippingCents).toBe(500);
    // total: 3900 + 195 + 500 = 4595
    expect(result.totals.totalCents).toBe(4595);
  });

  it("propagates priceFetcher rejection", async () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
    };
    await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
      "price service down",
    );
  });

  it("propagates asyncTaxProvider rejection", async () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service error")),
    };
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
      "tax service error",
    );
  });

  it("checkout does not mutate the cart's internal lines", async () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(9999),
    };
    await cart.checkout({ priceFetcher });
    // Cart's internal state should still use the original price
    expect(cart.totals().subtotalCents).toBe(2000);
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([0, 100, 99999])("returns 0 for subtotal %i", (subtotal) => {
    expect(policy.computeDiscountCents(subtotal)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    expect(policy.computeDiscountCents(-500)).toBe(0);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([-1, 101, NaN, Infinity, -Infinity])(
      "rejects out-of-range percent %s",
      (percent) => {
        expect(() => new PercentageDiscountPolicy(percent)).toThrow(RangeError);
      },
    );

    it.each([0, 50, 100])("accepts valid percent %i", (percent) => {
      expect(() => new PercentageDiscountPolicy(percent)).not.toThrow();
    });
  });

  it("computes 10% of 1000 = 100", () => {
    const policy = new PercentageDiscountPolicy(10);
    expect(policy.computeDiscountCents(1000)).toBe(100);
  });

  it("rounds down to nearest cent", () => {
    const policy = new PercentageDiscountPolicy(33);
    // 33% of 100 = 33.0 exactly
    expect(policy.computeDiscountCents(100)).toBe(33);
    // 33% of 101 = 33.33 → floor = 33
    expect(policy.computeDiscountCents(101)).toBe(33);
  });

  it("returns 0 for zero subtotal", () => {
    const policy = new PercentageDiscountPolicy(50);
    expect(policy.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    const policy = new PercentageDiscountPolicy(50);
    expect(policy.computeDiscountCents(-100)).toBe(0);
  });

  it("100% discount returns full subtotal", () => {
    const policy = new PercentageDiscountPolicy(100);
    expect(policy.computeDiscountCents(5000)).toBe(5000);
  });

  it("0% discount returns 0", () => {
    const policy = new PercentageDiscountPolicy(0);
    expect(policy.computeDiscountCents(5000)).toBe(0);
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([-1, -100])("rejects negative amount %i", (amount) => {
      expect(() => new FixedAmountDiscountPolicy(amount)).toThrow(RangeError);
    });

    it("rejects non-integer amount", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

    it("accepts zero", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  it("returns fixed amount when subtotal exceeds it", () => {
    const policy = new FixedAmountDiscountPolicy(500);
    expect(policy.computeDiscountCents(1000)).toBe(500);
  });

  it("caps discount at subtotal when subtotal is less than fixed amount", () => {
    const policy = new FixedAmountDiscountPolicy(500);
    expect(policy.computeDiscountCents(300)).toBe(300);
  });

  it("returns 0 for zero subtotal", () => {
    const policy = new FixedAmountDiscountPolicy(500);
    expect(policy.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    const policy = new FixedAmountDiscountPolicy(500);
    expect(policy.computeDiscountCents(-100)).toBe(0);
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policies array", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all child policies against the original subtotal", () => {
      const policies = [
        new PercentageDiscountPolicy(10), // 10% of 1000 = 100
        new FixedAmountDiscountPolicy(200), // fixed 200
      ];
      const composite = new CompositeDiscountPolicy(policies, "sum");
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-500)).toBe(0);
    });

    it("clamps negative child discount to 0 before summing", () => {
      const negativePolicy = {
        computeDiscountCents: () => -100,
      };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // -100 is clamped to 0, plus 200 = 200
      expect(composite.computeDiscountCents(1000)).toBe(200);
    });

    it("defaults to sum mode when not specified", () => {
      const policies = [
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(200),
      ];
      const composite = new CompositeDiscountPolicy(policies);
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const policies = [
        new PercentageDiscountPolicy(10), // 10% of 1000 = 100 → remaining 900
        new FixedAmountDiscountPolicy(200), // 200 off 900 → remaining 700
      ];
      const composite = new CompositeDiscountPolicy(policies, "chain");
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("ordering matters in chain mode", () => {
      const policiesA = [
        new FixedAmountDiscountPolicy(200), // 200 off 1000 → remaining 800
        new PercentageDiscountPolicy(10), // 10% of 800 = 80
      ];
      const policiesB = [
        new PercentageDiscountPolicy(10), // 10% of 1000 = 100 → remaining 900
        new FixedAmountDiscountPolicy(200), // 200 off 900
      ];
      const compositeA = new CompositeDiscountPolicy(policiesA, "chain");
      const compositeB = new CompositeDiscountPolicy(policiesB, "chain");
      expect(compositeA.computeDiscountCents(1000)).toBe(280);
      expect(compositeB.computeDiscountCents(1000)).toBe(300);
    });

    it("caps each step at remaining subtotal", () => {
      const policies = [
        new FixedAmountDiscountPolicy(800), // 800 off 1000 → remaining 200
        new FixedAmountDiscountPolicy(500), // 500 capped to 200 → remaining 0
      ];
      const composite = new CompositeDiscountPolicy(policies, "chain");
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(100)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("clamps negative child discount to 0 in chain mode", () => {
      const negativePolicy = {
        computeDiscountCents: () => -50,
      };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(100)],
        "chain",
      );
      // negative clamped to 0, then 100 off 1000
      expect(composite.computeDiscountCents(1000)).toBe(100);
    });
  });
});

