+  const brackets = [
+    { upToGrams: 500, costCents: 300 },
+    { upToGrams: 1000, costCents: 600 },
+    { upToGrams: 5000, costCents: 1200 },
+  ];
+
+  describe("constructor validation", () => {
+    it("rejects empty brackets array", () => {
+      expect(() => new WeightBasedShippingCalculator([])).toThrow(
+        "at least one weight bracket is required",
+      );
+    });
+
+    it("rejects bracket with non-positive upToGrams", () => {
+      expect(
+        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
+      ).toThrow(RangeError);
+    });
+
+    it("rejects bracket with negative costCents", () => {
+      expect(
+        () => new WeightBasedShippingCalculator([{ upToGrams: 500, costCents: -1 }]),
+      ).toThrow(RangeError);
+    });
+
+    it("rejects non-integer upToGrams", () => {
+      expect(
+        () => new WeightBasedShippingCalculator([{ upToGrams: 500.5, costCents: 100 }]),
+      ).toThrow(RangeError);
+    });
+
+    it("rejects non-integer costCents", () => {
+      expect(
+        () => new WeightBasedShippingCalculator([{ upToGrams: 500, costCents: 1.5 }]),
+      ).toThrow(RangeError);
+    });
+
+    it("rejects negative overflowCostCents", () => {
+      expect(
+        () => new WeightBasedShippingCalculator(
+          [{ upToGrams: 500, costCents: 100 }],
+          -1,
+        ),
+      ).toThrow(RangeError);
+    });
+
+    it("rejects non-integer overflowCostCents", () => {
+      expect(
+        () => new WeightBasedShippingCalculator(
+          [{ upToGrams: 500, costCents: 100 }],
+          10.5,
+        ),
+      ).toThrow(RangeError);
+    });
+  });
+
+  it("returns 0 for empty cart", () => {
+    const calc = new WeightBasedShippingCalculator(brackets);
+    expect(calc.computeShippingCents([], 1000)).toBe(0);
+  });
+
+  it("returns 0 when total weight is 0 (no weight specified)", () => {
+    const lines: CartLine[] = [
+      { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 1 },
+    ];
+    const calc = new WeightBasedShippingCalculator(brackets);
+    expect(calc.computeShippingCents(lines, 1000)).toBe(0);
+  });
+
+  it("selects the first bracket that covers the weight", () => {
+    const calc = new WeightBasedShippingCalculator(brackets);
+    // 400g → first bracket (≤500g) → 300 cents
+    expect(calc.computeShippingCents([makeLine("a", 400)], 1000)).toBe(300);
+  });
+
+  it("selects bracket at exact boundary", () => {
+    const calc = new WeightBasedShippingCalculator(brackets);
+    // exactly 500g → first bracket
+    expect(calc.computeShippingCents([makeLine("a", 500)], 1000)).toBe(300);
+    // exactly 501g → second bracket
+    expect(calc.computeShippingCents([makeLine("a", 501)], 1000)).toBe(600);
+  });
+
+  it("selects the heaviest bracket for weight at its boundary", () => {
+    const calc = new WeightBasedShippingCalculator(brackets);
+    expect(calc.computeShippingCents([makeLine("a", 5000)], 1000)).toBe(1200);
+  });
+
+  it("uses overflow cost when weight exceeds all brackets", () => {
+    const calc = new WeightBasedShippingCalculator(brackets, 2000);
+    expect(calc.computeShippingCents([makeLine("a", 6000)], 1000)).toBe(2000);
+  });
+
+  it("uses heaviest bracket cost as overflow when no overflow specified", () => {
+    const calc = new WeightBasedShippingCalculator(brackets);
+    expect(calc.computeShippingCents([makeLine("a", 6000)], 1000)).toBe(1200);
+  });
+
+  it("sorts brackets internally regardless of input order", () => {
+    const unsorted = [
+      { upToGrams: 5000, costCents: 1200 },
+      { upToGrams: 500, costCents: 300 },
+      { upToGrams: 1000, costCents: 600 },
+    ];
+    const calc = new WeightBasedShippingCalculator(unsorted);
+    expect(calc.computeShippingCents([makeLine("a", 400)], 1000)).toBe(300);
+  });
+
+  it("sums weight across multiple lines", () => {
+    const calc = new WeightBasedShippingCalculator(brackets);
+    const lines = [makeLine("a", 300, 2), makeLine("b", 200, 1)];
+    // total = 300*2 + 200*1 = 800 → second bracket (≤1000g) → 600
+    expect(calc.computeShippingCents(lines, 1000)).toBe(600);
+  });
+});
